package org.mockito.internal.invocation;

import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.exceptions.PrintableInvocation;
import org.mockito.internal.debugging.Location;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.invocation.realmethod.RealMethod;
import org.mockito.internal.matchers.*;
import org.mockito.internal.reporting.PrintSettings;
import org.mockito.internal.reporting.PrintingFriendlyInvocation;
import org.mockito.internal.util.*;
import org.mockito.invocation.InvocationOnMock;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class Invocation_callRealMethod_TriageGen0Test {

    public static class TestService {
        public String sayHello(String name) {
            return "Hello, " + name;
        }

        public void doNothing() {
        }

        public int getNumber() {
            return 42;
        }

        public void throwException() throws Exception {
            throw new Exception("Real error");
        }
    }

    @Test
    public void testCallRealMethod_ReturnsValue() throws Throwable {
        TestService realService = new TestService();
        Method method = TestService.class.getMethod("sayHello", String.class);
        Object[] args = new Object[]{"World"};

        // MockitoMethod is an interface, we can mock it or use a dummy if needed. 
        // In internal testing, we provide the required dependencies.
        MockitoMethod mockitoMethod = org.mockito.internal.invocation.MockitoMethod.nullInstance();

        Invocation invocation = new Invocation(
                realService, 
                mockitoMethod, 
                args, 
                1, 
                method
        );

        Object result = invocation.callRealMethod();
        assertEquals("Hello, World", result);
    }

    @Test
    public void testCallRealMethod_VoidMethod() throws Throwable {
        TestService realService = new TestService();
        Method method = TestService.class.getMethod("doNothing");
        Object[] args = new Object[0];
        MockitoMethod mockitoMethod = org.mockito.internal.invocation.MockitoMethod.nullInstance();

        Invocation invocation = new Invocation(
                realService, 
                mockitoMethod, 
                args, 
                1, 
                method
        );

        Object result = invocation.callRealMethod();
        assertNull(result);
    }

    @Test
    public void testCallRealMethod_PrimitiveReturn() throws Throwable {
        TestService realService = new TestService();
        Method method = TestService.class.getMethod("getNumber");
        Object[] args = new Object[0];
        MockitoMethod mockitoMethod = org.mockito.internal.invocation.MockitoMethod.nullInstance();

        Invocation invocation = new Invocation(
                realService, 
                mockitoMethod, 
                args, 
                1, 
                method
        );

        Object result = invocation.callRealMethod();
        assertEquals(Integer.valueOf(42), result);
    }

    @Test(expected = Exception.class)
    public void testCallRealMethod_ThrowsException() throws Throwable {
        TestService realService = new TestService();
        Method method = TestService.class.getMethod("throwException");
        Object[] args = new Object[0];
        MockitoMethod mockitoMethod = org.mockito.internal.invocation.MockitoMethod.nullInstance();

        Invocation invocation = new Invocation(
                realService, 
                mockitoMethod, 
                args, 
                1, 
                method
        );

        invocation.callRealMethod();
    }
}
